/**
 * Messages, residential R5: `quo-send`'s tech path, the pure part (`to-dos/gc-mode/messages/RESIDENTIAL_BUILD_PLAN.md`
 * → R5, on branch spike/gc-mode). Job Mode's **Message the customer** asks for a phone line by its id, with only the
 * blanks the tech typed. The server makes the text itself, with the sheet's own kernel (`jobModeMessageCustomer.ts`:
 * `jobModeFills` for what the app knows, `previewOf` for what is left), so no free text passes through a blank.
 *
 * - The request: `{ from: 'job_mode', customerId, contactId (may be null), jobId, quickReplyId, fills }`. Any body the
 *   client sends is never read. A typed blank holds 40 characters at most, on one line.
 * - The line: one of the phone's lines (the team's, for customers, with a place, not removed) that needs neither money
 *   nor the page link (`onPhone`). Typed words fill only the blanks the app cannot, so they never stand in for a name.
 * - The phone: the number they last texted from, else the first phone on their contact.
 */

import type { PortalLang } from '../gc/portalI18n.ts'
import { onPhone, previewOf } from '../jobModeText.ts'
import type { BlankFills } from '../quickReplies/blanks.ts'

/** The most characters a typed blank holds. */
export const TYPED_MAX = 40

/** The tech path's request, read. */
export interface TechSendBody {
  customerId: string
  /** The thread the sheet read, or null when there was none to read. */
  contactId: string | null
  jobId: string
  quickReplyId: string
  /** The blanks the tech typed, by blank: `{ minutes: '15' }`. */
  fills: Record<string, string>
}

/** The tech path's words, each a sentence the sheet shows as it is. */
export const TECH_SEND_WORDS = {
  badRequest: 'The text is missing its job, its customer or its line.',
  badFill: `A word you type holds ${TYPED_MAX} characters at most, on one line.`,
  notTech: 'Only a tech on this job sends from Job Mode.',
  noCustomer: 'This job has no customer yet.',
  wrongCustomer: 'That job is not this customer’s.',
  noPhone: 'They have no phone number on file. Use Something else.',
  notOnPhone: 'That line is not on the phone.',
  offPhone: 'That line needs the office. Use Something else.',
} as const

/** Whether a request is Job Mode's: it takes the tech path, not the reply box's. */
export function isJobModeSend(json: unknown): boolean {
  return !!json && typeof json === 'object' && !Array.isArray(json) && (json as Record<string, unknown>).from === 'job_mode'
}

const BLANK_KEY = /^[a-z][a-z ]{0,19}$/

/** The tech path's request, read; the words when something in it cannot go. Any `body` is left unread. */
export function parseTechSendBody(json: unknown): { ok: true; body: TechSendBody } | { ok: false; words: string } {
  if (!isJobModeSend(json)) return { ok: false, words: TECH_SEND_WORDS.badRequest }
  const o = json as Record<string, unknown>
  const id = (v: unknown) => (typeof v === 'string' && v.trim() ? v.trim() : null)
  const customerId = id(o.customerId)
  const jobId = id(o.jobId)
  const quickReplyId = id(o.quickReplyId)
  if (!customerId || !jobId || !quickReplyId) return { ok: false, words: TECH_SEND_WORDS.badRequest }
  const raw = o.fills ?? {}
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { ok: false, words: TECH_SEND_WORDS.badFill }
  const fills: Record<string, string> = {}
  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!BLANK_KEY.test(key) || typeof value !== 'string') return { ok: false, words: TECH_SEND_WORDS.badFill }
    const typed = value.trim()
    if (typed.length > TYPED_MAX || /[\r\n]/.test(typed)) return { ok: false, words: TECH_SEND_WORDS.badFill }
    if (typed) fills[key] = typed
  }
  return { ok: true, body: { customerId, contactId: id(o.contactId), jobId, quickReplyId, fills } }
}

/** A phone line as `quick_replies` keeps it. */
export interface PhoneLineRecord {
  text: string
  textEs: string | null
  forKind: string
  scope: string
  phoneOrder: number | null
  removed: boolean
}

export type TechSendText = { ok: true; text: string } | { ok: false; refused: 'notOnPhone' | 'offPhone' | 'blankOpen'; words: string }

/**
 * The text the tech's press sends: the line in the customer's language, the app's fills from the record (`app`, as
 * `jobModeFills` reads them), then the tech's typed words for the blanks the app left. Refused when the line is not on
 * the phone, needs money or the page link, or still has a blank open.
 */
export function composeTechText(line: PhoneLineRecord, app: BlankFills, typed: Readonly<Record<string, string>>, lang: PortalLang): TechSendText {
  if (line.removed || line.scope !== 'team' || line.forKind !== 'customer' || line.phoneOrder == null) {
    return { ok: false, refused: 'notOnPhone', words: TECH_SEND_WORDS.notOnPhone }
  }
  const words = { text: line.text, textEs: line.textEs }
  if (!onPhone(words)) return { ok: false, refused: 'offPhone', words: TECH_SEND_WORDS.offPhone }
  // Typed words fill only what the app could not: never a name, a job or a window the record holds.
  const asked = new Set(previewOf(words, app, {}, lang).asks.map((a) => a.key))
  const own = Object.fromEntries(Object.entries(typed).filter(([key]) => asked.has(key)))
  const shown = previewOf(words, app, own, lang)
  return shown.stop ? { ok: false, refused: 'blankOpen', words: shown.stop } : { ok: true, text: shown.text }
}

/** A number on a contact. */
export interface PhoneChannel {
  id: string
  kind: string
  value: string
  createdAt: string
}

/** The number the text goes to: the one they last texted from, else their first phone. Null when they have none. */
export function pickPhone(channels: readonly PhoneChannel[], lastInChannelId: string | null): PhoneChannel | null {
  const phones = channels.filter((c) => c.kind === 'phone' && c.value.trim())
  return (
    phones.find((c) => c.id === lastInChannelId) ??
    [...phones].sort((a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt) || a.id.localeCompare(b.id))[0] ??
    null
  )
}
